INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66635826', 66635826, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Perjalanan Dinas dalam dan luar kota dalam rangka Advokasi dan Sosialisasi Standar Pangan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 111299000, 'January 2026', 'APBN - PNBP (D), APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', 'Kegiatan ini mencakup kegiatan Advokasi dan Sosialisasi Standar Pangan yang dilaksanakan melalui perjalanan dinas dalam dan luar kota, dengan penyelenggaraan rapat/pertemuan fullday di luar kantor baik dalam kota maupun di kota Yogyakarta dan Makassar, guna memperluas jangkauan advokasi dan sosialisasi standar pangan kepada pemangku kepentingan di berbagai wilayah.', 'Paket kegiatan yang digunakan adalah Perjalanan Dinas Dalam dan Luar Kota dalam rangka Advokasi dan Sosialisasi Standar Pangan. Cakupan pembiayaan meliputi beberapa komponen utama, yaitu biaya paket kegiatan rapat/pertemuan fullday yang diselenggarakan di luar kantor dalam kota sebagai bagian dari rangkaian kegiatan advokasi dan sosialisasi di wilayah setempat, serta biaya paket kegiatan rapat/pertemuan fullday di luar kota yang dilaksanakan di kota Yogyakarta dan Makassar sebagai lokasi sasaran sosialisasi standar pangan di luar wilayah ibu kota. Selain itu, cakupan pembiayaan juga mencakup biaya penginapan bagi peserta selama pelaksanaan kegiatan di luar kota, khususnya di kota Yogyakarta dan Makassar, guna memastikan kelancaran dan kenyamanan pelaksanaan kegiatan perjalanan dinas. Keseluruhan komponen biaya tersebut merupakan kebutuhan operasional yang diperlukan dalam mendukung efektivitas pelaksanaan advokasi dan sosialisasi standar pangan secara menyeluruh di berbagai wilayah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2896005);
