INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66633150', 66633150, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KOTA BATAM', 'Konsumsi rapat pertemuan tim petugas kab/kota', 'Barang', 'E-Purchasing', 'Kepulauan Riau, Batam (Kota)', 310500000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 4500, OK, @ 69000 )', '1. Konsumsi rapat pertemuan tim petugas kab/kota ( 4500, OK, @ 69000 );', 'Spesifikasi Pekerjaan Konsumsi rapat berupa makanan ringan (snack box) atau makan berat (nasi kotak) sesuai kebutuhan kegiatan. Dilengkapi dengan minuman (air mineral/teh/kopi/juice). Makanan dalam kondisi segar, higienis, dan layak konsumsi. Diproduksi oleh penyedia yang memiliki standar kebersihan yang baik. Tidak menggunakan bahan yang telah kedaluwarsa. Snack box minimal terdiri dari 2–3 jenis makanan (misal: kue basah, roti, atau gorengan) dan 1 minuman. Nasi kotak minimal terdiri dari: nasi, lauk utama (ayam/daging/ikan), sayur, sambal, dan buah/air mineral. Menggunakan kemasan box yang rapi, bersih, dan aman untuk makanan. Mudah didistribusikan dan tidak mudah rusak. Konsumsi dikirim sesuai jadwal kegiatan rapat/pertemuan. Lokasi pengiriman di wilayah kab/kota sesuai permintaan. Ketepatan waktu pengiriman menjadi bagian dari penilaian kinerja penyedia. Harga maksimal per paket sebesar Rp69.000 (sudah termasuk pajak dan biaya distribusi).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2897248);
