INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66635824', 66635824, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Belanja Bahan dalam rangka Persiapan Posisi Indonesia pada Pertemuan Internasional', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 43213000, 'January 2026', 'APBN - PNBP (D), APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Kegiatan ini mencakup kegiatan Persiapan Posisi Indonesia pada Pertemuan Internasional yang meliputi kebutuhan bahan penunjang berupa penjilidan dan pencetakan dokumen, serta penyediaan konsumsi berupa makan siang dan snack dalam pertemuan pembahasan.', 'Paket kegiatan yang digunakan adalah Belanja Bahan dalam rangka Persiapan Posisi Indonesia pada Pertemuan Internasional. Cakupan pembiayaan meliputi beberapa komponen kebutuhan bahan, yaitu biaya penjilidan dan pencetakan dokumen yang dipersiapkan sebagai bahan referensi dan materi pendukung dalam pertemuan pembahasan, biaya makan siang yang disediakan bagi seluruh peserta selama pelaksanaan pertemuan berlangsung, serta biaya snack sebagai konsumsi pendukung dalam sesi pembahasan. Keseluruhan komponen belanja bahan tersebut merupakan kebutuhan mendasar yang diperlukan guna memastikan kelancaran dan efektivitas pelaksanaan pertemuan dalam rangka persiapan posisi Indonesia pada Pertemuan Internasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2898740);
